import{_ as l,o as e,c as i,a2 as o}from"./chunks/framework.A5mep7Fe.js";const _=JSON.parse('{"title":"🧭 02 · 面试流程与技巧","description":"","frontmatter":{},"headers":[],"relativePath":"09-面试实战/02-面试流程与技巧.md","filePath":"09-面试实战/02-面试流程与技巧.md","lastUpdated":1786806808000}'),t={name:"09-面试实战/02-面试流程与技巧.md"};function r(n,a,h,s,d,c){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="🧭-02-·-面试流程与技巧" tabindex="-1">🧭 02 · 面试流程与技巧 <a class="header-anchor" href="#🧭-02-·-面试流程与技巧" aria-label="Permalink to &quot;🧭 02 · 面试流程与技巧&quot;">​</a></h1><blockquote><p>知己知彼。AI 岗典型流程：简历筛 → 笔试/机考 → 技术面（2-4 轮）→ 主管/交叉面 → HR 面。本篇逐轮拆解。</p></blockquote><hr><h2 id="一、各轮应对策略" tabindex="-1">一、各轮应对策略 <a class="header-anchor" href="#一、各轮应对策略" aria-label="Permalink to &quot;一、各轮应对策略&quot;">​</a></h2><h3 id="_1-笔试-机考-算法为主" tabindex="-1">1. 笔试 / 机考（算法为主） <a class="header-anchor" href="#_1-笔试-机考-算法为主" aria-label="Permalink to &quot;1. 笔试 / 机考（算法为主）&quot;">​</a></h3><ul><li>常考：数据结构与算法（LeetCode 中等为主）、少量 ML 概念</li><li>准备：刷 <code>04-刷题指南</code> + 本篇 <code>03-手撕代码题</code></li><li>注意：边界条件、复杂度分析、沟通思路</li></ul><h3 id="_2-技术一面-基础-项目" tabindex="-1">2. 技术一面（基础 + 项目） <a class="header-anchor" href="#_2-技术一面-基础-项目" aria-label="Permalink to &quot;2. 技术一面（基础 + 项目）&quot;">​</a></h3><ul><li>深挖简历项目（STAR 追问），基础概念（Transformer/Attention/RAG/Agent）</li><li>策略：用「第一性原理」回答，主动画结构、写公式</li><li>不会的：诚实 + 说思路，别硬编</li></ul><h3 id="_3-技术二三面-深度-设计" tabindex="-1">3. 技术二三面（深度 + 设计） <a class="header-anchor" href="#_3-技术二三面-深度-设计" aria-label="Permalink to &quot;3. 技术二三面（深度 + 设计）&quot;">​</a></h3><ul><li>算法岗：推导（LoRA/RLHF）、手撕、系统设计</li><li>开发岗：系统设计（高并发 AI 服务）、分布式</li><li>策略：展现「本质判断」与「权衡意识」</li></ul><h3 id="_4-主管-交叉面-广度-软素质" tabindex="-1">4. 主管 / 交叉面（广度 + 软素质） <a class="header-anchor" href="#_4-主管-交叉面-广度-软素质" aria-label="Permalink to &quot;4. 主管 / 交叉面（广度 + 软素质）&quot;">​</a></h3><ul><li>问「你怎么看 X 技术/行业」「遇到冲突怎么处理」</li><li>策略：用 <code>00-导论</code> 的判断框架，展现思考深度与成熟</li></ul><h3 id="_5-hr-面" tabindex="-1">5. HR 面 <a class="header-anchor" href="#_5-hr-面" aria-label="Permalink to &quot;5. HR 面&quot;">​</a></h3><ul><li>聊薪资预期、职业规划、离职原因、到岗时间</li><li>策略：薪资留区间、展现稳定性与意愿（详见 <code>05-薪资</code>）</li></ul><h2 id="二、通用技巧" tabindex="-1">二、通用技巧 <a class="header-anchor" href="#二、通用技巧" aria-label="Permalink to &quot;二、通用技巧&quot;">​</a></h2><ul><li><strong>先澄清再答</strong>：确认问题边界，避免答偏</li><li><strong>结构化表达</strong>：结论先行 + 分点展开（金字塔原理）</li><li><strong>用图/公式辅助</strong>：复杂概念画出来</li><li><strong>主动引导</strong>：把话题引向你擅长的项目/知识点</li><li><strong>展现学习力</strong>：被问住时展示「如何查、如何学」</li></ul><h2 id="三、反问面试官-加分区" tabindex="-1">三、反问面试官（加分区） <a class="header-anchor" href="#三、反问面试官-加分区" aria-label="Permalink to &quot;三、反问面试官（加分区）&quot;">​</a></h2><ul><li>「这个岗位当前最大的技术挑战是什么？」</li><li>「团队的技术栈和迭代节奏？」</li><li>「这个职位预期 6 个月要达成什么？」</li><li>避免一上来只问薪资/加班</li></ul><h2 id="四、高频追问-模拟" tabindex="-1">四、高频追问（模拟） <a class="header-anchor" href="#四、高频追问-模拟" aria-label="Permalink to &quot;四、高频追问（模拟）&quot;">​</a></h2><p><strong>Q：遇到不会的问题怎么办？</strong></p><blockquote><p>先承认不熟悉，再给「我会怎么分析/查资料去解决」的思路，展现方法论与诚实。硬编比不会更扣分。</p></blockquote><p><strong>Q：怎么体现「本质判断」？</strong></p><blockquote><p>答任何技术都补一句「它的代价/局限/适用边界」，并说明「在什么场景我会选别的」。这区别于背题者。</p></blockquote><hr><p>➡️ 下一步：<a href="./03-高频手撕代码题">03-高频手撕代码题</a></p>',25)])])}const b=l(t,[["render",r]]);export{_ as __pageData,b as default};
